eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   serviceDetailPages: () => (/* binding */ serviceDetailPages)\n/* harmony export */ });\nconst serviceDetailPages = {\n    \"motor-repair-rewinding\": {\n        eyebrow: \"Wet-Stator Motor Specialists\",\n        title: \"BCP Motor Repair & Rewinding\",\n        lead: \"Specialist repair and rewind support for the wet-stator motors at the heart of sealless Boiler Circulation Pumps.\",\n        intro: \"The motor is the heart of a sealless boiler circulation pump. Its stator and rotor run in water at system pressure and temperature, so the winding insulation, protective cans and bearings all work under demanding conditions. When something fails, a general motor shop is not enough. DEI VOX repairs and rewinds BCP wet-stator motors as a dedicated specialty.\",\n        introImage: {\n            src: \"/images/motor-repair-rewinding-2.png\",\n            alt: \"Engineer working on a boiler circulation pump motor assembly\"\n        },\n        images: [\n            {\n                src: \"/images/motor-repair-rewinding-1.png\",\n                alt: \"Technicians inspecting a large boiler circulation pump motor assembly\"\n            },\n            {\n                src: \"/images/motor-repair-rewinding-2.png\",\n                alt: \"Pump motor assembly being handled in an engineering workshop\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Understanding the BCP Motor\",\n                text: \"In a sealless BCP, the pump and motor share one shaft inside a single pressure boundary. That removes the shaft seal and its leak path. The motor is a water-filled induction motor: a thin stator can protects the windings, a rotor can protects the rotor, and circulating water lubricates the internal bearings. A cooling circuit keeps the motor cavity at a safe temperature. Winding insulation, can integrity, bearings and cooling-water quality all affect motor life.\"\n            },\n            {\n                heading: \"Signs Your BCP Motor Needs Attention\",\n                type: \"list\",\n                items: [\n                    \"Falling insulation-resistance readings\",\n                    \"Changes in winding resistance or phase imbalance\",\n                    \"Rising vibration or unusual noise\",\n                    \"Rising motor-cavity temperature or cooling-circuit problems\",\n                    \"Evidence of water or debris contamination in the motor\",\n                    \"Bearing wear found during an inspection or outage\",\n                    \"Trips or abnormal current during start-up or warm standby\"\n                ],\n                note: \"If you see these signs, send the nameplate, test readings and fault history for a free technical opinion.\"\n            },\n            {\n                heading: \"Motor Repair & Rewinding Services\",\n                type: \"cards\",\n                items: [\n                    {\n                        title: \"Inspection & failure analysis\",\n                        text: \"Condition report with measurements and photographs.\"\n                    },\n                    {\n                        title: \"Rewinding\",\n                        text: \"Removal of failed windings and rewinding to the required design and insulation system.\"\n                    },\n                    {\n                        title: \"Stator and rotor cans\",\n                        text: \"Inspection, repair or replacement, subject to assessment.\"\n                    },\n                    {\n                        title: \"Bearing restoration\",\n                        text: \"Journal and thrust bearing inspection, refurbishment or replacement.\"\n                    },\n                    {\n                        title: \"Rotor and assembly\",\n                        text: \"Rotor balancing and assembly checks.\"\n                    },\n                    {\n                        title: \"Cooling and pressure boundary\",\n                        text: \"Cooling-circuit and pressure-boundary checks.\"\n                    },\n                    {\n                        title: \"Testing & documentation\",\n                        text: \"Records of the tests carried out.\"\n                    },\n                    {\n                        title: \"Obsolete components\",\n                        text: \"Reverse engineering of motor components from measurements and samples.\"\n                    },\n                    {\n                        title: \"Complete pump overhaul\",\n                        text: \"Motor and hydraulic end can be serviced together when required.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Our Repair & Rewinding Process\",\n                type: \"steps\",\n                items: [\n                    {\n                        title: \"Receipt & incoming inspection\",\n                        text: \"The motor is logged, photographed and checked against the nameplate and available drawings.\"\n                    },\n                    {\n                        title: \"Initial electrical tests\",\n                        text: \"Insulation resistance, winding resistance and other applicable tests are recorded before teardown.\"\n                    },\n                    {\n                        title: \"Teardown & condition report\",\n                        text: \"Components are measured; the failure mode and likely root cause are documented.\"\n                    },\n                    {\n                        title: \"Scope & quotation\",\n                        text: \"A clear scope, price and timeline are provided for approval before work proceeds.\"\n                    },\n                    {\n                        title: \"Rewinding & repair\",\n                        text: \"Work follows controlled procedures, with materials and insulation system matched to the design.\"\n                    },\n                    {\n                        title: \"Reassembly & fit checks\",\n                        text: \"Clearances, alignment and assembly dimensions are verified.\"\n                    },\n                    {\n                        title: \"Final testing\",\n                        text: \"Electrical, pressure-boundary and mechanical checks are carried out as applicable.\"\n                    },\n                    {\n                        title: \"Documentation & dispatch\",\n                        text: \"Test records and a repair summary accompany export-ready packing.\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"pump-overhaul-refurbishment\": {\n        eyebrow: \"Planned BCP Service\",\n        title: \"BCP Pump Overhaul & Refurbishment\",\n        lead: \"Specialist overhaul support to assess wear, restore components and document the condition of Boiler Circulation Pumps.\",\n        intro: \"A boiler circulation pump runs continuously at high pressure and temperature. Wear, erosion, bearing deterioration and thermal cycling can reduce performance and raise the risk of an unplanned stop. A planned overhaul lets the condition be assessed and repair decisions made ahead of an outage. DEI VOX supports BCP overhauls, including subcontract, overflow and white-label projects with overseas service companies.\",\n        introImage: {\n            src: \"/images/pump-overhaul-refurbishment-3.png\",\n            alt: \"Boiler circulation pump being serviced in a workshop\"\n        },\n        images: [\n            {\n                src: \"/images/pump-overhaul-refurbishment-1.png\",\n                alt: \"Boiler circulation pump components prepared for overhaul\"\n            },\n            {\n                src: \"/images/pump-overhaul-refurbishment-2.png\",\n                alt: \"Inspection and refurbishment work on a pump assembly\"\n            },\n            {\n                src: \"/images/pump-overhaul-refurbishment-3.png\",\n                alt: \"Large boiler circulation pump being serviced in a workshop\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"When to Plan an Overhaul\",\n                text: \"The source guidance suggests planning an overhaul after every 30,000-40,000 running hours or 4-5 years of operation, whichever comes first. Actual intervals should be assessed against equipment requirements, operating history and the applicable maintenance plan.\",\n                type: \"list\",\n                items: [\n                    \"A scheduled outage or inspection interval has been reached\",\n                    \"Pump head, flow or efficiency is falling\",\n                    \"Vibration or noise is rising\",\n                    \"Bearing wear is found during inspection or condition monitoring\",\n                    \"Leakage is present at flanges or joints\",\n                    \"Erosion or damage is found on internal parts\",\n                    \"A motor failure calls for a full pump inspection\",\n                    \"A plant life-extension or reliability programme is planned\"\n                ],\n                note: \"To request an initial technical opinion, share the nameplate, operating data and fault history.\"\n            },\n            {\n                heading: \"What We Overhaul\",\n                type: \"groups\",\n                groups: [\n                    {\n                        title: \"Pump end (hydraulic section)\",\n                        items: [\n                            \"Impeller inspection, repair or replacement, and balancing\",\n                            \"Diffuser and casing erosion and wear assessment, repair and dimensional restoration\",\n                            \"Wear-ring and clearance restoration against applicable design values\",\n                            \"Shaft inspection, straightness check, and repair or replacement assessment\"\n                        ]\n                    },\n                    {\n                        title: \"Bearings & rotating assembly\",\n                        items: [\n                            \"Journal and thrust bearing inspection, refurbishment or replacement\",\n                            \"Sleeve and bearing-seat measurement and restoration\",\n                            \"Rotor assembly dynamic balancing and fit checks\"\n                        ]\n                    },\n                    {\n                        title: \"Pressure boundary & joints\",\n                        items: [\n                            \"Flange faces, gasket seats and sealing-surface inspection and restoration\",\n                            \"Stud, nut and bolting inspection and replacement as required\",\n                            \"Main-joint preparation, assembly and verification\"\n                        ]\n                    },\n                    {\n                        title: \"Cooling circuit, auxiliaries & motor\",\n                        items: [\n                            \"Heat exchanger, cooling-line and auxiliary-component inspection\",\n                            \"Motor inspection, rewind or repair as part of the same overhaul when required\"\n                        ]\n                    }\n                ]\n            },\n            {\n                heading: \"Our Overhaul Process\",\n                type: \"steps\",\n                items: [\n                    {\n                        title: \"Receipt & incoming inspection\",\n                        text: \"The pump is logged, photographed and checked against the nameplate and available drawings.\"\n                    },\n                    {\n                        title: \"Pre-overhaul checks\",\n                        text: \"Initial measurements and condition are recorded before teardown.\"\n                    },\n                    {\n                        title: \"Teardown & cleaning\",\n                        text: \"Parts are dismantled in a controlled manner, tagged and cleaned.\"\n                    },\n                    {\n                        title: \"Measurement & condition report\",\n                        text: \"Critical dimensions, wear, damage and likely root causes are documented with photographs.\"\n                    },\n                    {\n                        title: \"Scope & quotation\",\n                        text: \"A clear scope, price and timeline are submitted for approval before work proceeds.\"\n                    },\n                    {\n                        title: \"Refurbishment & replacement\",\n                        text: \"Components are repaired or replaced to the agreed scope.\"\n                    },\n                    {\n                        title: \"Assembly & alignment\",\n                        text: \"Clearances, fits and assembly dimensions are verified.\"\n                    },\n                    {\n                        title: \"Balancing & testing\",\n                        text: \"Dynamic balancing and other agreed tests are carried out.\"\n                    },\n                    {\n                        title: \"Documentation & dispatch\",\n                        text: \"Test records and a repair summary accompany export-ready packing.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Frequently Asked Questions\",\n                type: \"faq\",\n                items: [\n                    {\n                        question: \"How do I know whether a pump needs an overhaul or only a repair?\",\n                        answer: \"A condition report compares measured wear against design values and includes photographs and a recommendation, helping you make an evidence-based decision.\"\n                    },\n                    {\n                        question: \"Do you overhaul pumps from different manufacturers?\",\n                        answer: \"Share the nameplate, drawings and previous repair reports so feasibility can be confirmed.\"\n                    },\n                    {\n                        question: \"What information do you need to quote?\",\n                        answer: \"The nameplate, photographs, operating data, fault history, drawings and earlier overhaul records are useful.\"\n                    },\n                    {\n                        question: \"Can you overhaul the pump and motor together?\",\n                        answer: \"Yes. The pump end and motor can be handled as one project, subject to assessment.\"\n                    },\n                    {\n                        question: \"Can you work behind our brand?\",\n                        answer: \"The source document describes subcontract and white-label support for service companies, with customer relationships respected.\"\n                    },\n                    {\n                        question: \"Can you work on site?\",\n                        answer: \"In-situ machining and field support may be discussed based on the work and site conditions.\"\n                    },\n                    {\n                        question: \"How long does an overhaul take?\",\n                        answer: \"The source document gives a typical estimate of 7-10 days per pump. Actual timing depends on the findings, scope and parts availability.\"\n                    },\n                    {\n                        question: \"What warranty is provided?\",\n                        answer: \"The source document states a warranty aligned with the standard OEM warranty. Confirm applicable terms in the project quotation.\"\n                    },\n                    {\n                        question: \"Can you supply spare parts?\",\n                        answer: \"Parts can be included in a quote request, including assessment of reverse-engineered components for obsolete designs.\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"testing-quality-assurance\": {\n        eyebrow: \"Inspection, Testing & Documentation\",\n        title: \"Testing & Quality Assurance\",\n        lead: \"Every overhaul and rewind includes inspection, measurement, testing and documentation, so the repair is supported by records.\",\n        intro: \"A boiler circulation pump cannot be assessed on appearance alone. Its condition has to be measured, and the repair verified before it returns to service. DEI VOX describes quality as part of the whole job, from incoming inspection and teardown measurements through repair, testing and documentation.\",\n        introImage: {\n            src: \"/images/testing-quality-assurance-2.png\",\n            alt: \"Pump component undergoing a dimensional quality inspection\"\n        },\n        images: [\n            {\n                src: \"/images/testing-quality-assurance-1.png\",\n                alt: \"DEI VOX quality management certificate\"\n            },\n            {\n                src: \"/images/testing-quality-assurance-2.png\",\n                alt: \"Pump component undergoing a dimensional inspection\"\n            },\n            {\n                src: \"/images/testing-quality-assurance-3.jpeg\",\n                alt: \"Quality inspection equipment used during pump service\"\n            },\n            {\n                src: \"/images/testing-quality-assurance-4.png\",\n                alt: \"Technician performing an inspection in the workshop\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Certified Management Systems\",\n                text: \"The source document lists management-system certifications to ISO 9001:2015, ISO 14001:2015 and ISO 45001:2018. View the certificate details and downloadable documents on the certificates page.\",\n                links: [\n                    {\n                        label: \"View Certificates (PDF)\",\n                        href: \"/iso-certificate\"\n                    }\n                ]\n            },\n            {\n                heading: \"Our Quality Process, Step by Step\",\n                type: \"steps\",\n                items: [\n                    {\n                        title: \"Incoming inspection\",\n                        text: \"The unit is received, logged, photographed and checked against its nameplate and paperwork; transit damage is recorded.\"\n                    },\n                    {\n                        title: \"Pre-work checks\",\n                        text: \"Initial electrical and mechanical readings are recorded before teardown.\"\n                    },\n                    {\n                        title: \"Teardown & measurement\",\n                        text: \"Components are tagged and measured against design values; wear, damage and likely causes are documented.\"\n                    },\n                    {\n                        title: \"Scope approval\",\n                        text: \"Findings and recommendations are sent for approval before repair begins.\"\n                    },\n                    {\n                        title: \"Controlled repair\",\n                        text: \"Work follows documented procedures and materials are matched to the job.\"\n                    },\n                    {\n                        title: \"In-process checks\",\n                        text: \"Critical dimensions, fits and clearances are verified at key stages.\"\n                    },\n                    {\n                        title: \"Final testing & release\",\n                        text: \"Applicable tests are recorded and the job record reviewed before release for packing.\"\n                    },\n                    {\n                        title: \"Packing & dispatch\",\n                        text: \"Export-ready packing is accompanied by a documentation pack.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Testing We Perform\",\n                type: \"groups\",\n                groups: [\n                    {\n                        title: \"Pump overhaul\",\n                        items: [\n                            \"Dimensional inspection of critical parts against design values\",\n                            \"Clearance and fit verification at assembly\",\n                            \"Dynamic balancing of the rotating assembly\",\n                            \"Non-destructive examination of repaired or critical components, as applicable\",\n                            \"Hydrostatic pressure test\",\n                            \"Vibration or run test\"\n                        ]\n                    },\n                    {\n                        title: \"Motor repair & rewinding\",\n                        items: [\n                            \"Insulation-resistance and polarisation checks\",\n                            \"Winding-resistance measurement\",\n                            \"High-voltage and surge testing\",\n                            \"Hydrostatic test of the motor pressure boundary\",\n                            \"Rotor balancing and vibration checks\",\n                            \"No-load test\"\n                        ]\n                    }\n                ]\n            },\n            {\n                heading: \"Customer Inspection Options\",\n                type: \"list\",\n                items: [\n                    \"Customer or inspector witness at agreed hold points, in person\",\n                    \"Remote witness by live video\",\n                    \"Third-party inspection by an agency nominated by the customer\",\n                    \"Hold points and an inspection plan agreed before work starts\"\n                ],\n                note: \"Witness arrangements and the inspection plan are agreed for each project.\"\n            },\n            {\n                heading: \"Confidentiality & Data Protection\",\n                text: \"Drawings, reports and test data are treated as confidential. DEI VOX will sign an NDA on request and use technical information to deliver the relevant job.\"\n            },\n            {\n                heading: \"Frequently Asked Questions\",\n                type: \"faq\",\n                items: [\n                    {\n                        question: \"Which standards do you work to?\",\n                        answer: \"The stated management-system certifications are ISO 9001:2015, ISO 14001:2015 and ISO 45001:2018. Technical acceptance follows the design values, customer specifications or applicable standard agreed for the job.\"\n                    },\n                    {\n                        question: \"Can my customer witness the tests?\",\n                        answer: \"In-person, remote or third-party witnessing can be arranged, with hold points agreed in advance.\"\n                    },\n                    {\n                        question: \"What does the test report include?\",\n                        answer: \"The tests carried out, measured values, dates and relevant personnel or approvals.\"\n                    },\n                    {\n                        question: \"Are test instruments calibrated?\",\n                        answer: \"The source document states instruments are calibrated at defined intervals and records are kept.\"\n                    },\n                    {\n                        question: \"Do you issue certificates of conformity for parts?\",\n                        answer: \"The source document states certificates of conformity can be issued; requirements should be confirmed for the specific part and scope.\"\n                    },\n                    {\n                        question: \"How long are job records retained?\",\n                        answer: \"The source document states a 10-year retention period.\"\n                    },\n                    {\n                        question: \"What happens if a test result is outside tolerance?\",\n                        answer: \"Work stops, the customer is informed, and options and the next step are agreed before continuing.\"\n                    },\n                    {\n                        question: \"What warranty applies to repaired units?\",\n                        answer: \"The source document states the standard OEM warranty. Confirm applicable terms in the project quotation.\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"reverse-engineering-custom-components\": {\n        eyebrow: \"Obsolete & Long-Lead Components\",\n        title: \"Reverse Engineering & Custom Components\",\n        lead: \"A discontinued part does not have to mean a discontinued pump. DEI VOX measures, models, manufactures and verifies replacement BCP components.\",\n        intro: \"Boiler circulation pumps can outlive their documentation, manufacturer support or original supply chain. When a critical component is obsolete or the OEM lead time does not fit an outage, reverse engineering offers another route. Work starts from a worn part, sample or available data and develops a replacement with records showing how it was made and checked.\",\n        introImage: {\n            src: \"/images/reverse-engineering-components-1.png\",\n            alt: \"Pump component inspected for reverse engineering\"\n        },\n        images: [\n            {\n                src: \"/images/reverse-engineering-components-1.png\",\n                alt: \"Engineering inspection of a pump component for reverse engineering\"\n            },\n            {\n                src: \"/images/reverse-engineering-components-2.png\",\n                alt: \"Measurement and modelling work for a custom replacement component\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"When Reverse Engineering Makes Sense\",\n                type: \"list\",\n                items: [\n                    \"The part is obsolete or the OEM no longer supports the design\",\n                    \"OEM lead time is too long for the outage window\",\n                    \"Drawings are lost, incomplete or inaccurate\",\n                    \"The pump has been modified and its as-built condition differs from the drawing\",\n                    \"A recurring failure suggests the part may need improvement, not just copying\",\n                    \"Spare parts need to be stocked for a mixed fleet of older units\"\n                ]\n            },\n            {\n                heading: \"Our Reverse Engineering Process\",\n                type: \"steps\",\n                items: [\n                    {\n                        title: \"Submit the part & data\",\n                        text: \"Send the sample or worn part, plus available drawings, photographs, operating conditions and failure history.\"\n                    },\n                    {\n                        title: \"Feasibility review\",\n                        text: \"Engineers assess condition, complexity and risks, and confirm whether reliable reproduction is feasible.\"\n                    },\n                    {\n                        title: \"Measurement\",\n                        text: \"Critical dimensions, tolerances and surface features are measured.\"\n                    },\n                    {\n                        title: \"Material identification\",\n                        text: \"Material is identified through analysis or specification review.\"\n                    },\n                    {\n                        title: \"Engineering & modelling\",\n                        text: \"A 3D model and manufacturing drawing are created and reviewed against operating conditions.\"\n                    },\n                    {\n                        title: \"Improvement review\",\n                        text: \"If wear or failure suggests a weakness, improvement options are presented for the customer to consider.\"\n                    },\n                    {\n                        title: \"Customer approval\",\n                        text: \"The drawing, material specification and proposed approach are submitted for sign-off before manufacture.\"\n                    },\n                    {\n                        title: \"Manufacture\",\n                        text: \"The component is machined and finished to the approved drawing.\"\n                    },\n                    {\n                        title: \"Inspection & verification\",\n                        text: \"The finished part is checked against the drawing and, where possible, trial-fitted with mating parts.\"\n                    },\n                    {\n                        title: \"Documentation & dispatch\",\n                        text: \"Inspection records, material records and the final drawing accompany export-ready packing.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Custom Components & Repair Tooling\",\n                text: \"Beyond replacement parts, DEI VOX can discuss custom components for special situations, including adapter parts, repair fixtures and special tools for in-situ work. Share the intended application so feasibility can be assessed.\"\n            },\n            {\n                heading: \"Submit a Part for Evaluation\",\n                text: \"Share the component, available drawings or photographs, operating conditions and failure history for an initial feasibility review. The source document states a response target of 24 business hours.\",\n                links: [\n                    {\n                        label: \"Submit a Part for Evaluation\",\n                        href: \"/contact?subject=Spare%20Parts%20Request\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"emergency-outage-support\": {\n        eyebrow: \"Urgent BCP Assistance\",\n        title: \"Emergency / Outage Support\",\n        lead: \"When a boiler circulation pump or motor puts a unit at risk, contact DEI VOX for technical triage and to discuss an expedited response.\",\n        intro: \"DEI VOX provides plant operators with technical triage, expedited repair planning and urgent-spares support when a Boiler Circulation Pump issue threatens an outage or restart date. The fastest realistic route depends on the equipment, information available, scope and parts availability.\",\n        introImage: {\n            src: \"/images/emergency-outage-support-1.jpeg\",\n            alt: \"Field engineer inspecting a pump assembly during urgent service work\"\n        },\n        images: [\n            {\n                src: \"/images/emergency-outage-support-1.jpeg\",\n                alt: \"Field engineer inspecting a pump assembly during urgent service work\"\n            }\n        ],\n        urgentContact: true,\n        sections: [\n            {\n                heading: \"Direct Urgent Contact\",\n                text: \"Call or message the service team and share the pump or motor nameplate, fault details and required outage date. The source document lists service hours as Monday to Saturday, 09:00-19:00 IST, with urgent-line monitoring beyond those hours.\",\n                contact: true\n            },\n            {\n                heading: \"What Counts as an Emergency\",\n                type: \"list\",\n                items: [\n                    \"A BCP or motor failure that threatens or has caused a unit outage\",\n                    \"A failure during an outage that threatens the restart date\",\n                    \"An urgent need for a critical spare to avoid or shorten an outage\",\n                    \"Unexpected teardown damage requiring an immediate repair decision\",\n                    \"A recurring fault needing rapid root-cause support\"\n                ],\n                note: \"If you are unsure whether your case qualifies, send the details so feasibility can be discussed.\"\n            },\n            {\n                heading: \"How We Can Help\",\n                type: \"cards\",\n                items: [\n                    {\n                        title: \"Rapid technical triage\",\n                        text: \"Initial review of the nameplate, readings, photographs and fault history.\"\n                    },\n                    {\n                        title: \"Expedited inspection & repair\",\n                        text: \"Priority intake may be discussed for teardown, a condition report and repair plan.\"\n                    },\n                    {\n                        title: \"Urgent motor rewind or pump overhaul\",\n                        text: \"Agree the shortest realistic programme and scope in writing.\"\n                    },\n                    {\n                        title: \"Urgent spares\",\n                        text: \"Check supply from stock or assess fast manufacture of critical components.\"\n                    },\n                    {\n                        title: \"In-situ machining\",\n                        text: \"Discuss on-site casing repair where the job and site conditions allow.\"\n                    },\n                    {\n                        title: \"Field & remote support\",\n                        text: \"Coordinate engineer support for removal, inspection or installation, including remote coordination where agreed.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Response Targets\",\n                type: \"response\",\n                note: \"The following are targets stated in the source document, not guaranteed service levels. Actual response and turnaround depend on complete information, scope, equipment condition and parts availability.\",\n                items: [\n                    {\n                        stage: \"Acknowledgement of request\",\n                        target: \"Within 1 hour\",\n                        notes: \"Named contact assigned\"\n                    },\n                    {\n                        stage: \"Initial technical opinion\",\n                        target: \"Within 2 hours\",\n                        notes: \"After receipt of complete data\"\n                    },\n                    {\n                        stage: \"Quotation or plan\",\n                        target: \"Within 3 hours\",\n                        notes: \"Scope, price and realistic timeline\"\n                    },\n                    {\n                        stage: \"Start of work after approval and receipt\",\n                        target: \"4-5 days\",\n                        notes: \"Subject to scope and parts availability\"\n                    },\n                    {\n                        stage: \"Typical expedited turnaround\",\n                        target: \"About 1 week\",\n                        notes: \"Depends on damage found and materials\"\n                    }\n                ]\n            },\n            {\n                heading: \"How to Request Urgent Support\",\n                type: \"steps\",\n                items: [\n                    {\n                        title: \"Contact us immediately\",\n                        text: \"Use WhatsApp, phone or the urgent request link.\"\n                    },\n                    {\n                        title: \"Send what you have\",\n                        text: \"A nameplate photo, pump and motor model, fault description, readings, photographs and outage dates are useful.\"\n                    },\n                    {\n                        title: \"Talk to an engineer\",\n                        text: \"Feasibility and the fastest realistic route are discussed.\"\n                    },\n                    {\n                        title: \"Approve the plan\",\n                        text: \"Scope, price and timeline are agreed in writing.\"\n                    },\n                    {\n                        title: \"Ship or mobilise\",\n                        text: \"Coordinate logistics for the unit, parts or engineers.\"\n                    },\n                    {\n                        title: \"Receive progress updates\",\n                        text: \"Updates are provided at intervals agreed for the project.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Information That Speeds Things Up\",\n                type: \"list\",\n                items: [\n                    \"Pump and motor make, model and serial number\",\n                    \"Operating conditions and run history\",\n                    \"Fault description, alarms, trips and readings\",\n                    \"Photographs or video of the damage\",\n                    \"Required completion date and delivery address\",\n                    \"Customer customs, inspection or documentation requirements\"\n                ],\n                note: \"Every hour counts. Send the details available, even if some information is incomplete.\"\n            }\n        ]\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/serviceDetailPages.js\n");

